mapper.select:
SELECT ast30_book_fund_fee_id AS book_fund_fee_id , ast30_corp_id AS corp_id , ast30_corp_cd AS corp_code , ast30_corp_nm AS corp_name , ast30_fund_cd AS fund_code , ast30_fund_nm AS fund_name , ast30_cur_cd AS cur_code , ast30_for_fee AS for_fee , ast30_fee AS fee FROM ( SELECT ast30_book_fund_fee.* , ast30_for_fee - COALESCE(ast30_for_fix_fee,0) as ast30_for_ty_fee , ast30_fee - COALESCE(ast30_fix_fee,0) as ast30_ty_fee , sys15_corp_cd as ast30_corp_cd , sys15_corp_nm as ast30_corp_nm FROM ast30_book_fund_fee LEFT OUTER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id WHERE ast30_company_id = #{p.companyId}
AND ast30_corp_id = #{p.corpId}
AND ast30_hold_date = CAST(#{p.holdDate} AS date) + INTERVAL '-1day' ) t WHERE UPPER(CONCAT(ast30_corp_cd,ast30_corp_nm,ast30_fund_cd,ast30_fund_nm)) LIKE '%'||UPPER(#{p.searchText})||'%' ORDER BY ast30_corp_cd, ast30_fund_cd

mapper.sql:
FROM ( SELECT t1.ast30_hold_date, t1.ast30_corp_id, t1.ast30_fund_cd, t1.ast30_fund_nm , t1.ast30_fee, t1.ast30_un_rcv_fee , COALESCE(icam10_diff_fee,0) AS ast30_diff_fee , COALESCE(icam10_occ_fee,0) AS ast30_occ_fee , COALESCE(icam10_draw_fee,0) AS ast30_draw_fee , COALESCE(t2.ast30_fee,0) AS ast30_pre_fee , ( SELECT SUM(a.ast30_fee_today) FROM ast30_book_fund_fee a WHERE a.ast30_company_id = t1.ast30_company_id AND a.ast30_ast_class_tree_id = t1.ast30_ast_class_tree_id AND a.ast30_corp_id = t1.ast30_corp_id AND a.ast30_fund_cd = t1.ast30_fund_cd AND a.ast30_hold_date BETWEEN CAST(TO_CHAR(t1.ast30_hold_date,'YYYYMM')||'01' AS DATE) AND t1.ast30_hold_date ) AS ast30_month_occ_fee FROM ast30_book_fund_fee t1 LEFT OUTER JOIN ast30_book_fund_fee t2 ON ( t2.ast30_hold_date = t1.ast30_hold_date + interval '-1day' AND t2.ast30_company_id = t1.ast30_company_id AND t2.ast30_ast_class_tree_id = t1.ast30_ast_class_tree_id AND t2.ast30_corp_id = t1.ast30_corp_id AND t2.ast30_fund_cd = t1.ast30_fund_cd ) LEFT OUTER JOIN ( SELECT icam10_company_id , icam10_std_date , icam10_fund_cd , SUM(icam10_diff_fee) AS icam10_diff_fee , SUM(CASE WHEN icam10_rmk_cd = 'P00' THEN icam10_diff_fee ELSE 0 END) AS icam10_occ_fee , SUM(CASE WHEN icam10_rmk_cd IN ('D20','D30') THEN icam10_diff_fee ELSE 0 END) AS icam10_draw_fee FROM ( SELECT * , f_calc_dual_fund_fee(icam10_company_id, icam10_icam_company_cd, icam10_fund_cd, icam10_std_date, icam10_fee) * CASE WHEN icam10_drcr_type = 'C' THEN 1 ELSE -1 END * f_nvl(icam10_fx_rate,1) AS icam10_diff_fee FROM icam10_fee WHERE icam10_company_id = #{p.companyId} AND icam10_std_date BETWEEN #{p.startDate} AND #{p.closeDate} ) icam10 GROUP BY icam10_company_id, icam10_std_date, icam10_fund_cd ) t3 ON ( icam10_company_id = t1.ast30_company_id AND icam10_std_date = t1.ast30_hold_date AND icam10_fund_cd = t1.ast30_fund_cd ) WHERE t1.ast30_company_id = #{p.companyId} AND t1.ast30_hold_date BETWEEN #{p.startDate} AND #{p.closeDate}
AND t1.ast30_fund_cd = #{p.fundCode}
) t WHERE upper(concat(ast30_fund_cd,ast30_fund_nm)) LIKE '%'||upper(#{p.searchText})||'%'

mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}
